   409  static int luaB_assert (lua_State *L) {
   410    if (l_likely(lua_toboolean(L, 1)))  /* condition is true? */
   411      return lua_gettop(L);  /* return all arguments */
   412    else {  /* error */
   413      luaL_checkany(L, 1);  /* there must be a condition */
   414      lua_remove(L, 1);  /* remove it */
   415      lua_pushliteral(L, "assertion failed!");  /* default message */
   416      lua_settop(L, 1);  /* leave only message (default if no other one) */
   417      return luaB_error(L);  /* call 'error' */
   418    }
   419  }
