   422  static int luaB_select (lua_State *L) {
   423    int n = lua_gettop(L);
   424    if (lua_type(L, 1) == LUA_TSTRING && *lua_tostring(L, 1) == '#') {
   425      lua_pushinteger(L, n-1);
   426      return 1;
   427    }
   428    else {
   429      lua_Integer i = luaL_checkinteger(L, 1);
   430      if (i < 0) i = n + i;
   431      else if (i > n) i = n;
   432      luaL_argcheck(L, 1 <= i, 1, "index out of range");
   433      return n - (int)i;
   434    }
   435  }
